namespace ghidra.features.codecompare.decompile;

using docking.action;
using ghidra.app.services;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util;

/**
 * An action for bringing up a side-by-side function comparison of callees with matching 
 * tokens.
 */
public class CompareFuncsFromMatchedTokensAction : AbstractMatchedCalleeTokensAction {
	private PluginTool tool;
	private static readonly string ACTION_NAME = "Compare Matching Callees";

	/**
	 * Constructor
	 * @param diffPanel diff Panel
	 * @param tool tool
	 */
	public CompareFuncsFromMatchedTokensAction(DecompilerCodeComparisonView diffPanel,
			PluginTool tool) : base(ACTION_NAME, tool.getName(), diffPanel, false)
    {
		this.tool = tool;

		MenuData menuData = new MenuData(new string[] { ACTION_NAME }, null, MENU_GROUP);
		setPopupMenuData(menuData);
		setHelpLocation(new HelpLocation(HELP_TOPIC, "Compare Matching Callees"));
	}

	/* @Override */
	protected void doCalleeActionPerformed(Function leftFunction, Function rightFunction) {
		FunctionComparisonService service = tool.getService(typeof(FunctionComparisonService));
		if (service == null) {
			Msg.error(this, "Function Comparison Service not found!");
			return;
		}
		service.createComparison(leftFunction, rightFunction);
	}

}
